<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { apiRequest } from '../lib/api';
import { useAppStore } from '../stores/app';
import type { EntityCategory, GeoEntity } from '../types';

interface ImportRun { id: string; filename?: string; format?: string; adapter?: string; status?: string; source?: string; entityType?: string; entityCount?: number; processedCount?: number; candidateCount?: number; errorCount?: number; createdAt?: string; updatedAt?: string; message?: string; }
interface ImportCandidate { id: string; ordinal?: number; name?: string; geom?: { type: string; coordinates: unknown }; geometry?: { type: string; coordinates: unknown }; validationStatus?: string; validationNote?: string; targetStatus?: string; possibleDuplicate?: boolean; duplicateEntity?: GeoEntity; processedEntityId?: string; }
const store = useAppStore();
const categories = ref<EntityCategory[]>([]); const imports = ref<ImportRun[]>([]); const selectedRun = ref<ImportRun | null>(null); const candidates = ref<ImportCandidate[]>([]); const selectedCandidateIds = ref<string[]>([]); const page = ref(1); const pageSize = ref(20); const totalCandidates = ref(0);
const format = ref('GEOJSON'); const adapter = ref('MANUAL'); const entityType = ref(''); const filename = ref(''); const source = ref('MANUAL'); const content = ref(''); const file = ref<File | null>(null); const busy = ref(false); const message = ref(''); const error = ref('');
const formats = ['GEOJSON', 'OSM_GEOJSON', 'KML', 'GPX', 'SHAPEFILE', 'OSM_PBF', 'PARKSERVE_US', 'WFS', 'ARCGIS_FEATURESERVER'];
const activeImports = computed(() => imports.value.filter(item => !['PROCESSED', 'FAILED', 'REJECTED'].includes(String(item.status || '').toUpperCase())));
const allSelected = computed(() => candidates.value.length > 0 && candidates.value.every(item => selectedCandidateIds.value.includes(item.id)));

function unwrap<T>(data: T | { items?: T }): T { return (data && typeof data === 'object' && 'items' in (data as object) ? (data as { items: T }).items : data) as T; }
function setError(value: unknown): void { error.value = value instanceof Error ? value.message : String(value); }
function readAsBase64(value: ArrayBuffer): string { let binary = ''; const bytes = new Uint8Array(value); const chunk = 0x8000; for (let offset = 0; offset < bytes.length; offset += chunk) binary += String.fromCharCode(...bytes.subarray(offset, Math.min(offset + chunk, bytes.length))); return btoa(binary); }
async function loadCategories(): Promise<void> { try { const data = await apiRequest<{ items: EntityCategory[] }>('/v1/entity-types'); categories.value = data.items || []; } catch (e) { setError(e); } }
async function loadImports(): Promise<void> { try { const data = await apiRequest<{ items: ImportRun[] }>('/v1/geodata/imports?pageSize=50'); imports.value = data.items || []; } catch (e) { setError(e); } }
async function queueImport(): Promise<void> {
  error.value = ''; message.value = '';
  if (!entityType.value) { error.value = 'Select the entity category for this dataset.'; return; }
  if (!file.value && !content.value.trim()) { error.value = 'Choose a file or paste source data.'; return; }
  busy.value = true;
  try {
    if (file.value) {
      const body = { adapter: adapter.value, format: format.value, entityType: entityType.value, source: source.value, filename: file.value.name, contentBase64: readAsBase64(await file.value.arrayBuffer()) };
      await apiRequest('/v1/geodata/imports/upload', { method: 'POST', body: JSON.stringify(body) });
    } else {
      await apiRequest('/v1/geodata/imports', { method: 'POST', body: JSON.stringify({ adapter: adapter.value, format: format.value, entityType: entityType.value, source: source.value, filename: filename.value || `pasted-${format.value.toLowerCase()}`, content: content.value }) });
    }
    content.value = ''; file.value = null; filename.value = ''; message.value = 'Import queued for preprocessing as candidate entities.'; await loadImports();
  } catch (e) { setError(e); } finally { busy.value = false; }
}
function chooseFile(event: Event): void { file.value = (event.target as HTMLInputElement).files?.[0] || null; if (file.value) filename.value = file.value.name; }
async function selectRun(run: ImportRun): Promise<void> { selectedRun.value = run; page.value = 1; selectedCandidateIds.value = []; await loadCandidates(); }
async function loadCandidates(): Promise<void> { if (!selectedRun.value) return; try { const data = await apiRequest<{ items: ImportCandidate[]; total?: number }>(`/v1/geodata/imports/${encodeURIComponent(selectedRun.value.id)}/candidates?page=${page.value}&pageSize=${pageSize.value}`); candidates.value = data.items || []; totalCandidates.value = Number(data.total || candidates.value.length); } catch (e) { setError(e); } }
function toggleAll(): void { selectedCandidateIds.value = allSelected.value ? [] : candidates.value.map(item => item.id); }
function toggleCandidate(id: string): void { selectedCandidateIds.value = selectedCandidateIds.value.includes(id) ? selectedCandidateIds.value.filter(item => item !== id) : [...selectedCandidateIds.value, id]; }
async function validateCandidates(validationStatus = 'VALID'): Promise<void> { if (!selectedRun.value || !selectedCandidateIds.value.length) return; try { await apiRequest(`/v1/geodata/imports/${encodeURIComponent(selectedRun.value.id)}/candidates/validate`, { method: 'POST', body: JSON.stringify({ candidateIds: selectedCandidateIds.value, validationStatus, validatorId: store.account?.id }) }); message.value = 'Candidate validation saved.'; await loadCandidates(); await loadImports(); } catch (e) { setError(e); } }
async function processCandidates(): Promise<void> { if (!selectedRun.value || !selectedCandidateIds.value.length) return; const targetStatus = window.prompt('Target status: CANDIDATE or APPROVED', 'CANDIDATE')?.toUpperCase(); if (!targetStatus || !['CANDIDATE', 'APPROVED'].includes(targetStatus)) return; try { await apiRequest(`/v1/geodata/imports/${encodeURIComponent(selectedRun.value.id)}/candidates/process`, { method: 'POST', body: JSON.stringify({ candidateIds: selectedCandidateIds.value, targetStatus, processorId: store.account?.id }) }); message.value = `Selected records queued as ${targetStatus}.`; await loadCandidates(); await loadImports(); } catch (e) { setError(e); } }
async function markProcessed(): Promise<void> { if (!selectedRun.value || !window.confirm('Mark this import as processed and remove its pending candidate records?')) return; try { await apiRequest(`/v1/geodata/imports/${encodeURIComponent(selectedRun.value.id)}/processed`, { method: 'POST', body: JSON.stringify({ processedBy: store.account?.id }) }); message.value = 'Import marked as processed.'; await loadImports(); selectedRun.value = null; candidates.value = []; } catch (e) { setError(e); } }
function candidateEntity(item: ImportCandidate): GeoEntity { return { id: item.id, name: item.name || 'Pre-processed entity', status: item.targetStatus || 'CANDIDATE', geometry: item.geometry || item.geom }; }
onMounted(async () => { await Promise.all([loadCategories(), loadImports()]); });
</script>

<template>
  <section class="page-heading"><div><p class="eyebrow">GEODATA PIPELINE</p><h1>Geodata imports</h1><p class="muted">Upload or paste a source dataset, preprocess it, review duplicates, then queue confirmed entities as candidates or approved entities.</p></div><button class="secondary" @click="loadImports">Refresh history</button></section>
  <div v-if="message" class="notice" role="status">{{ message }}</div><div v-if="error" class="error-card" role="alert">{{ error }}</div>
  <article class="panel"><div class="panel-heading"><div><h2>Queue a dataset</h2><p class="field-help">All imports start as candidate records. Binary formats should be uploaded; text formats may be pasted.</p></div></div><form class="form-grid" @submit.prevent="queueImport"><label>Format<select v-model="format"><option v-for="item in formats" :key="item" :value="item">{{ item }}</option></select></label><label>Adapter<select v-model="adapter"><option value="MANUAL">Manual upload</option><option value="OSM">OpenStreetMap</option><option value="PARKSERVE_US">ParkServe US</option><option value="WFS">WFS / ArcGIS</option><option value="LOCAL_GIS">Local government GIS</option></select></label><label>Feature category<select v-model="entityType" required><option value="">Select a category…</option><option v-for="category in categories" :key="category.code" :value="category.code">{{ category.label || category.code }}</option></select></label><label>Source label<input v-model="source" placeholder="OSM, municipal GIS, manual proposal…"></label><label class="wide">Paste source document<textarea v-model="content" :placeholder="file ? `File selected: ${file.name}` : 'Paste GeoJSON, KML, GPX, WFS or ArcGIS JSON here'"></textarea><small class="field-help">The text is optional when a file is selected.</small></label><label class="wide">Upload file<input type="file" accept=".json,.geojson,.kml,.gpx,.zip,.shp,.pbf,.csv" @change="chooseFile"><small v-if="file" class="field-help">Selected: {{ file.name }} ({{ Math.round(file.size / 1024) }} KB)</small></label><label v-if="!file">Source filename<input v-model="filename" placeholder="dataset.geojson"></label><div class="form-actions wide"><button class="primary" :disabled="busy" type="submit">{{ busy ? 'Uploading…' : 'Queue preprocessing' }}</button></div></form></article>
  <div class="split-layout"><article class="panel"><div class="panel-heading"><div><h2>Import history</h2><small class="muted">{{ activeImports.length }} active or waiting</small></div></div><div class="table-list"><button v-for="run in imports" :key="run.id" class="table-row" :class="{ selected: selectedRun?.id === run.id }" @click="selectRun(run)"><span><strong>{{ run.filename || run.id }}</strong><small>{{ run.format }} · {{ run.adapter }} · {{ run.createdAt || 'time unknown' }}</small></span><span class="status-pill" :class="(run.status || '').toLowerCase()">{{ run.status }}</span></button><p v-if="!imports.length" class="muted empty">No imports have been queued.</p></div></article><article v-if="selectedRun" class="panel"><div class="panel-heading"><div><p class="eyebrow">IMPORT DETAIL</p><h2>{{ selectedRun.filename || selectedRun.id }}</h2><p class="muted">{{ selectedRun.status }} · {{ selectedRun.entityCount ?? 0 }} source records · {{ selectedRun.candidateCount ?? 0 }} candidates</p></div><button class="secondary" @click="markProcessed">Mark import as processed</button></div><div class="info-grid"><div><span>Status</span><strong>{{ selectedRun.status }}</strong></div><div><span>Processed</span><strong>{{ selectedRun.processedCount ?? 0 }}</strong></div><div><span>Errors</span><strong>{{ selectedRun.errorCount ?? 0 }}</strong></div><div><span>Source</span><strong>{{ selectedRun.source || '—' }}</strong></div></div><h3>Validate pre-processed records</h3><div class="toolbar"><label class="check-field"><input type="checkbox" :checked="allSelected" @change="toggleAll"><span>Select all on page</span></label><button class="secondary" :disabled="!selectedCandidateIds.length" @click="validateCandidates('VALID')">Validate selected</button><button class="secondary" :disabled="!selectedCandidateIds.length" @click="validateCandidates('REJECTED')">Reject selected</button><button class="primary" :disabled="!selectedCandidateIds.length" @click="processCandidates">Queue selected</button></div><div class="candidate-list"><div v-for="item in candidates" :key="item.id" class="candidate-row"><input type="checkbox" :checked="selectedCandidateIds.includes(item.id)" @change="toggleCandidate(item.id)"><button class="candidate-name" @click="selectedCandidateIds = [item.id]">{{ item.name || 'Unnamed entity' }}</button><span>{{ item.validationStatus || 'PENDING' }}</span><span v-if="item.possibleDuplicate" class="warning-pill">Possible duplicate</span><small>{{ item.geometry?.type || item.geom?.type || 'No geometry' }}</small></div><p v-if="!candidates.length" class="muted empty">No pre-processed records for this import yet.</p></div><div class="pagination"><button class="secondary" :disabled="page <= 1" @click="page--; loadCandidates()">Previous</button><span>Page {{ page }} · {{ totalCandidates }} records</span><button class="secondary" :disabled="page * pageSize >= totalCandidates" @click="page++; loadCandidates()">Next</button></div></article><article v-else class="panel empty-state"><h2>Select an import</h2><p class="muted">Click an import above to inspect its processing status and pre-processed records.</p></article></div>
</template>
